package com.yangchengwei.easytrip.place.data
import androidx.room.*
import com.yangchengwei.easytrip.trip.data.TripEntity
@Entity(tableName="saved_places",foreignKeys=[ForeignKey(entity=TripEntity::class,parentColumns=["id"],childColumns=["tripId"],onDelete=ForeignKey.CASCADE)],indices=[Index("tripId"),Index(value=["id","tripId"],unique=true),Index(value=["tripId","amapPoiId"],unique=true)]) data class SavedPlaceEntity(@PrimaryKey val id:String,val tripId:String,val amapPoiId:String,val name:String,val address:String,val latitude:Double,val longitude:Double,val note:String?=null,val cityCode:String?=null)
@Entity(tableName="tags",foreignKeys=[ForeignKey(entity=TripEntity::class,parentColumns=["id"],childColumns=["tripId"],onDelete=ForeignKey.CASCADE)],indices=[Index("tripId"),Index(value=["id","tripId"],unique=true),Index(value=["tripId","tagNameNormalized"],unique=true)]) data class TagEntity(@PrimaryKey val id:String,val tripId:String,val name:String,val tagNameNormalized:String)
@Entity(tableName="saved_place_tags",primaryKeys=["savedPlaceId","tagId"],foreignKeys=[ForeignKey(entity=SavedPlaceEntity::class,parentColumns=["id","tripId"],childColumns=["savedPlaceId","tripId"],onDelete=ForeignKey.CASCADE),ForeignKey(entity=TagEntity::class,parentColumns=["id","tripId"],childColumns=["tagId","tripId"],onDelete=ForeignKey.CASCADE)],indices=[Index(value=["savedPlaceId","tripId"]),Index(value=["tagId","tripId"])]) data class SavedPlaceTagCrossRef(val savedPlaceId:String,val tagId:String,val tripId:String)
